/**
 * Pilot instrument (T70): redrawn SVG pictures for the MAP questions that depend on an image.
 * Source of truth: docs/cac/pilot/instrument_map_id.json (generated by ml/scripts/pilot_materials.py);
 * files are copied to public/pilot/. Flagged for teacher review before the session.
 */
export interface PilotFigure {
  src: string;
  alt: string;
}

const FIGURES: Record<number, PilotFigure> = {
  31772: { src: '/pilot/map-31772.svg', alt: 'Segitiga dibagi menjadi 9 segitiga kecil sama besar; 6 di antaranya diarsir.' },
  76870: { src: '/pilot/map-76870.svg', alt: 'Dua sisi segi banyak beraturan yang bertemu pada sudut dalam 144 derajat.' },
  91695: { src: '/pilot/map-91695.svg', alt: 'Pola titik: Pola 1 = 6 titik, Pola 2 = 10, Pola 3 = 14, Pola 4 = 18.' },
};

export function pilotFigure(mapQuestionId: number | null | undefined): PilotFigure | null {
  if (mapQuestionId == null) return null;
  return FIGURES[mapQuestionId] ?? null;
}

export const PILOT_FIGURE_IDS = Object.keys(FIGURES).map(Number);
